<?php
function parallel15(array $arguments):array{global $tmp;$jobs=[];foreach($arguments as $args){$p=proc_open(array_merge([PHP_BINARY,'-d','ffi.enable=1',__DIR__.'/connection_worker.php',$tmp.'/config.json'],$args),[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$p,$pipes];}$out=[];foreach($jobs as [$p,$pipes]){$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0 || $stderr!==''){throw new RuntimeException($stderr);}$out[]=trim($stdout);}return $out;}
test('015: four queries race four signed callbacks and credit once',static function()use($a){[$p,$user,$order]=payment15();$jobs=[];for($i=0;$i<8;$i++){$jobs[]=[$i%2?'query':'callback',(string)$user,(string)$order['id']];}$out=parallel15($jobs);same(4,count(array_filter($out,static function($v){return $v==='paid';})));same(100,funds($user));same(1,(int)$a->db->value("SELECT COUNT(*) FROM cy_audit WHERE action='payment.settled' AND target=?",[$order['order_no']]));});
test('015: eight concurrent badge grants create one grant and one notification',static function()use($a,$admin){$user=user14('badge-race');$badge=$a->badges->save($admin,['name'=>'Concurrent recognition','description'=>'Fixture','symbol'=>'shield','tone'=>'tide','active'=>1]);$before=(int)$a->db->value('SELECT COUNT(*) FROM cy_notifications WHERE user_id=?',[$user]);$out=parallel15(array_fill(0,8,['badge',(string)$user,(string)$badge,(string)$admin]));same(8,count($out));same(1,(int)$a->db->value('SELECT COUNT(*) FROM cy_user_badges WHERE user_id=? AND badge_id=?',[$user,$badge]));same($before+1,(int)$a->db->value('SELECT COUNT(*) FROM cy_notifications WHERE user_id=?',[$user]));});
